use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(rows) = input {
        let n = rows.len();
        let m = rows[0].as_array().unwrap().len();
        let mut result = vec![vec![0; n]; m];
        for i in 0..n {
            for j in 0..m {
                result[j][n - 1 - i] = rows[i][j].as_i64().unwrap();
            }
        }
        Value::Array(result.into_iter().map(|row| Value::Array(row.into_iter().map(|v| Value::Number(v.into())).collect())).collect())
    } else {
        Value::Null
    }
}
